import{_ as a,o,c as t,a2 as r}from"./chunks/framework.BDCokyix.js";const m=JSON.parse('{"title":"ADR-0001: Local daemon — superseded by in-process napi addon","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/adrs/0001-local-daemon-grpc.md","filePath":"architecture/adrs/0001-local-daemon-grpc.md","lastUpdated":1780254295000}'),n={name:"architecture/adrs/0001-local-daemon-grpc.md"};function s(i,e,d,c,l,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0001-local-daemon-—-superseded-by-in-process-napi-addon" tabindex="-1">ADR-0001: Local daemon — superseded by in-process napi addon <a class="header-anchor" href="#adr-0001-local-daemon-—-superseded-by-in-process-napi-addon" aria-label="Permalink to &quot;ADR-0001: Local daemon — superseded by in-process napi addon&quot;">​</a></h1><p><strong>Status:</strong> Superseded.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The desktop UI must interact with networking, storage, and cryptography without exposing network services.</p><h2 id="original-decision" tabindex="-1">Original decision <a class="header-anchor" href="#original-decision" aria-label="Permalink to &quot;Original decision&quot;">​</a></h2><p>Use a <strong>local daemon</strong> communicating with the UI via <strong>gRPC over Unix Domain Socket</strong>.</p><ul><li>No TCP ports exposed</li><li>Authenticated via IPC token</li><li>High performance</li><li>Small attack surface</li></ul><h2 id="current-state" tabindex="-1">Current state <a class="header-anchor" href="#current-state" aria-label="Permalink to &quot;Current state&quot;">​</a></h2><p>The desktop no longer spawns a separate daemon process. The peer / daemon runtime and the agent runtime both ship as <strong>library crates</strong> (<code>soma-daemon</code>, <code>soma-agentd</code>) linked into a napi-rs addon (<code>soma-node</code>) loaded directly by the Electron main process. All daemon operations go through in-process Rust calls; there is no socket, no gRPC, no <code>soma-socket</code> helper.</p><p>The original goals are preserved more cleanly than the gRPC topology achieved:</p><ul><li>No TCP ports exposed (still true; no transport at all).</li><li>Authentication is moot — every caller already runs inside the same Electron main process as the daemon library.</li><li>Performance is strictly better: zero serialization, zero context switches.</li><li>Attack surface shrank: no Unix-socket listener, no proto deserialization on the hot path.</li></ul><h2 id="why-this-adr-is-kept" tabindex="-1">Why this ADR is kept <a class="header-anchor" href="#why-this-adr-is-kept" aria-label="Permalink to &quot;Why this ADR is kept&quot;">​</a></h2><p>The decision recorded here informed today&#39;s structure: the <code>handle/</code> module inside <code>soma-daemon</code> (the in-process facade exposed via napi) is a direct descendant of the gRPC service, mapping the same operations onto plain Rust types. New ADRs should reference this one when discussing the desktop ↔ daemon boundary.</p>',13)])])}const u=a(n,[["render",s]]);export{m as __pageData,u as default};
